def p(*items):return ''.join(f'<p>{x}</p>' for x in items)
def code(s):return '<pre><code>'+escape(s)+'</code></pre>'
def math(s):return '<div class="math">'+escape(s)+'</div>'
def note(title,text):return f'<aside class="callout"><strong>{title}</strong><p>{text}</p></aside>'
def table(headers,rows):return '<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def bullets(items):return '<ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'

def chapter_content(page,lang):
    t=lambda en,zh:zh if lang=='zh' else en
    parts=[]
    def add(ident,title,intro,body,refs,figure=''):
        parts.append((f'{len(parts)+1:02} / FIELD NOTES',title,intro,body,ident,figure,refs))
    if page=='foundations':
        info=(t('Start with the property<br><em>you need to preserve</em>','先明确<br><em>要保护的属性</em>'),t('Security goals, byte-level conventions and the distinction between a primitive and a protocol.','先理解安全目标、字节约定，以及密码原语和协议的区别。'))
        add('goals',t('One message, several different goals','一条消息，多种安全目标'),t('Choose a construction only after naming the attacker and the protected property.','先写清攻击者和要保护的属性，再选择构造。'),table([t('Goal','目标'),t('Typical mechanism','典型机制'),t('What it does not settle','未解决的问题')],[
            (t('Confidentiality','机密性'),'AEAD',t('Who should be authorized to receive the key','谁应有权获得密钥')),
            (t('Integrity / shared-key authenticity','完整性 / 共享密钥认证'),'MAC / AEAD',t('Which key holder created the message','是哪一位密钥持有者创建消息')),
            (t('Publicly verifiable origin','可公开验证的来源'),t('Digital signature + trusted public key','数字签名 + 可信公钥'),t('Human intent, legal effect and resource authorization','人的意图、法律效力和资源授权')),
            (t('Freshness','新鲜度'),t('Challenge / sequence / replay state','挑战 / 序号 / 重放状态'),t('Encryption alone does not reject a replay','仅加密不能拒绝重放')),
        ]),['book','keymgmt'],'primitive-map')
        add('bytes',t('Algorithms process bytes, not visual meaning','算法处理字节，不处理视觉含义'),t('Encoding choices are part of the security design.','编码选择是安全设计的一部分。'),p(t('Hex and Base64 are representations, not encryption. UTF-8, normalization, field boundaries, byte order and signed serialization must be agreed on. The strings “ab” + “c” and “a” + “bc” collide under naïve concatenation even without a hash collision. Use a specified, unambiguous encoding and domain labels.','Hex 与 Base64 是表示方式，不是加密。UTF-8、规范化、字段边界、字节序及签名序列化必须约定。“ab” + “c” 与 “a” + “bc” 的朴素拼接相同，这不是 Hash 碰撞。应使用规定好的无歧义编码和域标签。'))+math('encode(protocol_id, version, role, length(field_1), field_1, length(field_2), field_2)'),['book','tls'])
        add('parameters',t('Read parameters before comparing “bits”','比较“位数”前先看参数'),t('Key size, block size, digest size and estimated security are different quantities.','密钥长度、分组长度、摘要长度和估计安全强度是不同量。'),p(t('AES-256 still has a 128-bit block. A 256-bit hash has a generic classical collision cost around 2^128, not 2^256. A 2048-bit RSA modulus and a 256-bit elliptic-curve field do not represent comparable key lengths by simple counting. Use the algorithm’s security analysis, parameter set and usage limits.','AES-256 的分组仍是 128 位。256 位 Hash 的通用经典碰撞成本约为 2^128，而非 2^256。2048 位 RSA 模数和 256 位椭圆曲线域不能按位数直接比较。应看算法安全分析、参数集及使用上限。'))+note(t('A primitive is a building block','原语只是积木'),t('A protocol adds identity, negotiation, transcript binding, state transitions and failure behavior. A successful decrypt or signature check is not the whole protocol.','协议还加入身份、协商、转录绑定、状态转换和失败行为。解密或验签成功不代表整个协议成功。')),['book','aes'])
    elif page=='symmetric':
        info=(t('From AES rounds<br><em>to encrypted records</em>','从 AES 的轮变换<br><em>到消息加密</em>'),t('Trace one AES block, compare seven modes, and see where IVs, counters, tweaks and authentication tags enter.','从单个 AES 分组开始，对照七种工作模式，弄清 IV、计数器、tweak 和认证标签各在哪一步发挥作用。'))
        add('primitives',t('AES and stream ciphers have different interfaces','AES 与流密码的接口不同'),
            t('AES is a keyed permutation on one 16-byte block. A mode defines how to use it on a message or a storage unit.','AES 对一个 16 字节块执行带密钥的可逆变换；工作模式定义如何用它处理消息或存储单元。'),
            table([t('Variant','算法'),t('Key length','密钥长度'),t('Block length','分组长度'),t('Rounds','轮数')],[
                ('AES-128',t('128 bits','128 位'),t('128 bits','128 位'),'10'),
                ('AES-192',t('192 bits','192 位'),t('128 bits','128 位'),'12'),
                ('AES-256',t('256 bits','256 位'),t('128 bits','128 位'),'14'),
            ])+p(t('ChaCha20 is a stream cipher with a keystream interface. AES exposes a forward and an inverse permutation. A mode such as CTR builds a keystream from repeated calls to the forward AES permutation.','ChaCha20 是直接产生密钥流的流密码。AES 提供正向和逆向置换；CTR 等模式通过多次调用正向 AES 来产生密钥流。')),['aes','chacha','book'])
        operations = ''.join(
            f'<article class="aes-transform"><h3>{name}</h3>{p(explanation)}{original_figure(t, filename, caption)}</article>'
            for name, filename, caption, explanation in round_steps(t)
        )
        add('aes-rounds',t('AES encryption and decryption','AES 加密与解密'),
            t('Track the 16-byte state through key expansion, reversible round transformations and the inverse cipher.','沿着密钥扩展、可逆的轮变换和逆向解密，追踪 16 字节状态。'),
            p(t('AES stores the block as a 4×4 byte matrix in column order, state[row,col] = input[4·col+row]. The first four bytes fill the first column. KeyExpansion splits the master key into 32-bit words and generates Nr+1 round keys, each 16 bytes. Every Nk words, RotWord rotates one word, SubWord applies the S-box, and Rcon adds a round constant before the XOR with the word Nk positions back. AES-256 also applies SubWord halfway through each eight-word group. Here Nk is 4, 6 or 8, and Nr is the round count.',
                'AES 按列把分组放进 4×4 字节矩阵，state[row,col] = input[4·col+row]，最前面 4 字节填满第一列。KeyExpansion 把主密钥拆成 32 位字，扩展出 Nr+1 个 16 字节轮密钥。每隔 Nk 个字，先用 RotWord 循环移位、SubWord 逐字节查 S 盒，再异或轮常量 Rcon，最后与前推 Nk 个位置的字异或。AES-256 还在每组八个字的中间额外执行 SubWord。这里 Nk 为 4、6 或 8，Nr 为轮数。'))
            +math('''AES Encrypt
  state ← AddRoundKey(input, RK[0])
  for r = 1…Nr−1:
    state ← SubBytes → ShiftRows → MixColumns → AddRoundKey(RK[r])
  output ← SubBytes → ShiftRows → AddRoundKey(RK[Nr])

AES Decrypt (inverse cipher)
  state ← AddRoundKey(ciphertext, RK[Nr])
  for r = Nr−1…1:
    state ← InvShiftRows → InvSubBytes → AddRoundKey(RK[r]) → InvMixColumns
  plaintext ← InvShiftRows → InvSubBytes → AddRoundKey(RK[0])''')
            +p(t('Each arrow acts on the current state. The inverse cipher uses the same expanded round keys in reverse order. The encryption final round and the corresponding inverse boundary omit column mixing.','每个箭头都对当前状态继续运算。逆密码使用相同的扩展轮密钥，顺序反过来；正向末轮及相应的逆向边界省去列混合。'))
            +f'<div class="aes-round-grid">{operations}</div>'
            +'<h3>'+t('Walk one AES-128 block','跟算一个 AES-128 分组')+'</h3>'
            +p(t('In NIST’s example, XOR the input with round key 0. The first byte is 0x6b ⊕ 0x2b = 0x40. Read the full state column by column. Compare the initial state and each step of round 1 against the intermediate values, then check the final ciphertext.',
                 '在 NIST 算例中，先把输入与第 0 轮密钥异或，第一个字节是 0x6b ⊕ 0x2b = 0x40。下面的十六进制值按列展开。可以核对初始状态和第 1 轮的每一步，再检查最终密文。'))
            +math('''Key / RK[0]    2b7e151628aed2a6abf7158809cf4f3c
Plaintext      6bc1bee22e409f96e93d7e117393172a
Initial XOR    40bfabf406ee4d3042ca6b997a5c5816
1 SubBytes     090862bf6f28e3042c747feeda4a6a47
1 ShiftRows    09287f476f746abf2c4a6204da08e3ee
1 MixColumns   529f16c2978615cae01aae54ba1a2659
1 AddRoundKey  f265e8d51fd2397bc3b9976d9076505c
Ciphertext     3ad77bb40d7a3660a89ecaf32466ef97'''),['aes','aes-example'])

        rows = [
            ('ECB', t('None','无'), t('Whole blocks','整块'), t('Independent blocks reveal repeated patterns','独立加密泄露重复块')),
            ('CBC', t('Unpredictable IV','不可预测 IV'), t('Whole blocks','整块'), t('Ciphertext chaining, confidentiality only','密文链接，仅机密性')),
            ('CTR', t('Distinct counter blocks','计数器块不重复'), t('Truncate last keystream block','可截取末块密钥流'), t('Parallel keystream, confidentiality only','可并行生成密钥流，仅机密性')),
            ('CFB', t('Unpredictable IV','不可预测 IV'), t('Whole segments','按段对齐'), t('Ciphertext feedback, confidentiality only','密文反馈，仅机密性')),
            ('OFB', t('Unique IV','唯一 IV'), t('Truncate last keystream block','可截取末块密钥流'), t('Keystream feedback, confidentiality only','密钥流反馈，仅机密性')),
            ('GCM', t('Unique nonce','唯一 Nonce'), t('Truncate last keystream block','可截取末块密钥流'), t('AEAD with tag and AAD','带 Tag 和 AAD 的认证加密')),
            ('XTS', t('Data-unit number','数据单元编号'), t('Ciphertext stealing','密文窃取'), t('Length-preserving storage confidentiality','等长的存储机密性')),
        ]
        add('aes-modes',t('Compare the AES modes','AES 模式对照'),
            t('The same block cipher can provide very different guarantees depending on what surrounds it.','底层都使用 AES，模式的输入和分组组织方式决定了各自的安全属性。'),
            table([t('Mode','模式'),t('Public input','公开输入'),t('Length handling','长度处理'),t('What the mode provides','模式特点')],
                [(f'<a href="#aes-{name.lower()}">{name}</a>', public, length, purpose) for name, public, length, purpose in rows])
            +p(t('In the formulas, E_K and D_K are the forward and inverse AES permutations under key K. P[i] and C[i] are plaintext and ciphertext blocks or segments, ⊕ is XOR, || concatenates bit strings, and MSB_n / LSB_n take the first / last n bits. Indices start at 1 unless indicated. Figures are unmodified Wikimedia Commons originals; the references below each mode link to the technical standards.',
                 '下文 E_K、D_K 表示密钥 K 下的 AES 正向、逆向置换，P[i]、C[i] 是明文和密文块或段，⊕ 表示异或，|| 表示比特串拼接，MSB_n / LSB_n 取前／后 n 位。除特别说明外，块编号从 1 开始。图采用 Wikimedia Commons 原图，各模式下方另附技术规范。')),['modes','gcm','xts'])
        for ident, name, title, intro, figures, formula, notes, reference in mode_details(t):
            illustrations = ''.join(original_figure(t, filename, caption) for filename, caption in figures)
            add('aes-'+ident, f'{name} · {title}', intro, illustrations+math(formula)+p(*notes), [reference])

        add('aead',t('AEAD authenticates ciphertext and visible context','AEAD 认证密文和可见上下文'),t('Use the mode’s defined nonce and tag requirements.','遵守模式定义的 Nonce 和 Tag 要求。'),math('(ciphertext, tag) = Seal(key, nonce, plaintext, associated_data)\nplaintext or FAIL = Open(key, nonce, ciphertext, tag, associated_data)')+p(t('AES-GCM and ChaCha20-Poly1305 combine encryption with authentication. Associated data is visible but authenticated: a version, tenant, content type or sequence number can be bound to a record. The receiver must supply the same data and reject authentication failure before using plaintext.','AES-GCM 与 ChaCha20-Poly1305 结合加密和认证。关联数据可见但经过认证，可绑定版本、租户、内容类型或序号。接收方必须提供相同关联数据，并在使用明文前拒绝认证失败。')),['gcm','chacha','library'],'aead')
        add('nonces',t('Uniqueness is a lifecycle problem','唯一性是生命周期问题'),t('A random nonce is not a universal solution to restarts and concurrency.','随机 Nonce 不能自动解决重启与并发。'),p(t('For AES-GCM, never reuse a nonce with the same key. A 96-bit nonce is the conventional efficient choice, subject to the specification’s bounds. ChaCha20-Poly1305 also requires uniqueness. Counter allocation must survive concurrent writers, crashes and VM snapshots; random allocation needs a collision budget. Key rotation does not help if old key/nonce state is restored.','AES-GCM 不应在相同密钥下复用 Nonce。96 位 Nonce 是常见的高效选择，但仍受规范上限约束。ChaCha20-Poly1305 也要求唯一性。计数器分配要处理并发、崩溃和 VM 快照；随机分配要计算碰撞预算。恢复旧 key/nonce 状态时，密钥轮换本身也不能解决问题。'))+math('C1 = P1 XOR S\nC2 = P2 XOR S\nC1 XOR C2 = P1 XOR P2  # if the same keystream S is reused')+note(t('Authenticity does not imply replay protection','真实性不等于防重放'),t('An unchanged authenticated record may verify twice. Track protocol sequence or request state separately. XTS disk encryption solves a different problem and does not provide AEAD-style data authentication.','未修改的认证记录可以验证两次。协议序号或请求状态需要另行跟踪。XTS 磁盘加密解决另一类问题，不提供 AEAD 式数据认证。')),['gcm','chacha'])
        add('practice',t('A useful implementation exercise','一个有用的实现练习'),t('Validate failure behavior as well as the round trip.','既验证正确往返，也验证失败行为。'),bullets([t('Encrypt one record, then alter ciphertext, tag and AAD independently; every altered record should fail authentication.','加密一条记录，分别修改密文、Tag 与 AAD；每个修改后的记录都应认证失败。'),t('Write down how nonce allocation remains unique across restarts and multiple writers.','写清 Nonce 分配如何在重启和多个写入者之间保持唯一。'),t('Set a record-size/key-usage budget from the chosen algorithm and protocol; do not invent a universal unlimited lifetime.','按所选算法及协议设置记录大小和密钥使用预算，不设想无限使用寿命。')]),['library'])
    elif page=='public-key':
        info=(t('Separate encryption,<br><em>key agreement and signatures</em>','分清加密<br><em>密钥协商与签名</em>'),t('Public keys remove the need for a pre-shared secret, but not the need to authenticate identities.','公钥减少预共享秘密需求，但并不消除身份认证需求。'))
        add('roles',t('Three operations with different security goals','三种操作，三类安全目标'),t('A key pair is not an interchangeable encrypt/sign interface.','密钥对不是可随意替换的 encrypt/sign 接口。'),table([t('Operation','操作'),t('Public input','公开输入'),t('Secret input / result','秘密输入 / 结果')],[
            (t('Public-key encryption','公钥加密'),t('Recipient encryption key','接收者加密公钥'),t('Recipient private key recovers plaintext','接收者私钥恢复明文')),
            (t('DH / KEM key establishment','DH / KEM 密钥建立'),t('DH shares or encapsulation key/ciphertext','DH 公共份额，或封装公钥 / 密文'),t('Private inputs produce shared keying material; KDF derives usage keys','私有输入产生共享密钥材料；KDF 派生用途密钥')),
            (t('Digital signature','数字签名'),t('Verification key + message + signature','验证公钥 + 消息 + 签名'),t('Signing key creates a signature, not a secret message','签名私钥产生签名，不产生秘密消息')),
        ])+p(t('RSA-OAEP is an encryption scheme; RSA-PSS is a signature scheme. Raw modular exponentiation is neither a safe message cipher nor a complete signature scheme. X25519 is for DH; Ed25519 is for signatures, despite both using related curve mathematics.','RSA-OAEP 是加密方案；RSA-PSS 是签名方案。原始模幂既不是安全消息加密，也不是完整签名方案。X25519 用于 DH，Ed25519 用于签名，尽管两者的曲线数学相关。')),['rsa','x25519','eddsa'],'public-roles')
        add('agreement',t('Understand agreement with a tiny worked example','用一个小例子理解协商'),t('The numbers below are deliberately insecure teaching values.','以下数字故意很小，只用于教学。'),math('p = 23, g = 5\nAlice: a = 6, A = g^a mod p = 8\nBob:   b = 15, B = g^b mod p = 19\nAlice: B^a mod p = 2\nBob:   A^b mod p = 2')+p(t('Real DH uses vetted groups and validates public inputs as required. Bare DH does not authenticate the peer: an active intermediary can negotiate a different secret with each side. Authenticate the exchange and bind roles and transcript. Ephemeral agreement can provide forward secrecy against later long-term-key compromise, under the protocol’s assumptions.','真实 DH 使用经过审查的群，并按要求校验公开输入。裸 DH 不认证对端：主动中间人可与双方分别协商秘密。应认证协商过程，并绑定角色和转录。临时密钥协商可在协议假设下，抵御之后长期密钥泄漏对历史会话的影响。')),['dh-paper','x25519','tls'])
        add('signatures',t('Signing depends on encoding, nonce handling and identity','签名依赖编码、Nonce 处理与身份'),t('ECDSA, EdDSA and RSA-PSS are schemes with specific rules.','ECDSA、EdDSA 与 RSA-PSS 都有各自规则。'),p(t('ECDSA requires secure per-message scalar generation: reused or biased values can expose the private key. Deterministic generation is one specified approach, not permission to invent a nonce rule. EdDSA uses its own deterministic design; hash/prehash/context variants must match exactly. Sign a specified representation with domain separation; verify with an authenticated key and appropriate algorithm constraints.','ECDSA 要求安全地产生每条消息的标量；复用或偏置可泄漏私钥。确定性生成是一种规定好的方案，不意味着可以自创 Nonce 规则。EdDSA 有自己的确定性设计；Hash、prehash、context 变体必须严格匹配。签署规定的表示并进行域分离，使用经过认证的公钥及算法约束验证。'))+note(t('A signature is not “private-key encryption”','签名不是“用私钥加密”'),t('Verification authenticates the signed bytes under a key. Confidentiality, certificate trust, authorization and replay checks are distinct.','验签认证的是某个密钥下的签署字节。机密性、证书信任、授权和重放检查是不同问题。')),['eddsa','rsa','book'])
        add('pki',t('A public key needs a trust path','公钥需要信任路径'),t('Certificates connect names and keys through a policy-controlled trust chain.','证书通过受策略约束的信任链连接名称和密钥。'),p(t('A certificate chain is not accepted merely because every signature is mathematically valid. Check the selected trust anchor, constraints, validity, intended usage, algorithm policy and revocation handling; TLS also checks the intended service name. Pinning and raw keys use different enrollment and rotation models. Losing trust-store control can defeat otherwise correct cryptography.','证书链不能仅因各个签名数学有效就被接受。应检查选定信任锚、约束、有效期、用途、算法策略和撤销处理；TLS 还需核对预期服务名。Pinning 与原始公钥采用不同的登记和轮换模型。失去信任库控制可破坏原本正确的密码机制。')),['tls','keymgmt'])
    elif page=='hashes':
        info=(t('A digest is not<br><em>an authenticator</em>','摘要不是<br><em>认证器</em>'),t('Hash functions, keyed authentication, key derivation and password storage have separate contracts.','Hash、带密钥认证、密钥派生和口令存储有不同要求。'))
        add('properties',t('Three resistance properties','三种抗攻击属性'),t('The work factors below are generic classical estimates for an ideal n-bit digest.','以下是理想 n 位摘要的通用经典工作量估计。'),table([t('Property','属性'),t('Attacker task','攻击者任务'),t('Generic cost','通用成本')],[
            (t('Preimage','原像'),t('Given y, find x with H(x)=y','给定 y，寻找满足 H(x)=y 的 x'),'≈ 2^n'),
            (t('Second preimage','第二原像'),t('Given x, find another x′ with the same hash','给定 x，寻找同 Hash 的另一 x′'),'≈ 2^n'),
            (t('Collision','碰撞'),t('Choose any distinct x,x′ with equal hashes','自选任意不同 x、x′ 使 Hash 相同'),'≈ 2^(n/2)'),
        ])+p(t('SHA-256 / SHA-512 are SHA-2 choices; SHA-3 uses a different sponge design, and SHAKE is an extendable-output function. A hash is deterministic and usually public. An attacker able to replace both a file and its published hash can preserve a successful comparison. MD5 and SHA-1 are historical examples of broken collision resistance, not choices for new signature-integrity designs.','SHA-256 / SHA-512 属于 SHA-2；SHA-3 使用不同的海绵结构，SHAKE 是可扩展输出函数。Hash 是确定性且通常公开的。若攻击者可同时替换文件及公布的 Hash，比较仍可成功。MD5 与 SHA-1 是碰撞安全被破坏的历史例子，不应用于新的签名完整性设计。')),['sha2','sha3','book'])
        add('mac',t('HMAC adds a shared authentication secret','HMAC 加入共享认证秘密'),t('A plain hash cannot identify who created a message.','普通 Hash 不能识别消息由谁创建。'),math('tag = HMAC(key, encoded_message)\naccept only if constant_time_compare(expected_tag, received_tag)')+p(t('HMAC uses a specific nested keyed-hash construction. Do not replace it with H(secret || message): Merkle–Damgård hashes can allow length extension in that construction. Every holder of the MAC key can create a valid tag, so HMAC does not offer public verification or distinguish those holders. Use different keys and domain labels across protocols.','HMAC 使用规定的嵌套带密钥 Hash 构造。不要替换为 H(secret || message)：Merkle–Damgård Hash 在这种构造下可出现长度扩展。每位 MAC 密钥持有者都可生成有效 Tag，因此 HMAC 不提供公开验证，也不区分这些持有者。跨协议使用不同密钥与域标签。')),['hmac'],'hash-mac-kdf')
        add('kdf',t('HKDF extracts and expands keying material','HKDF 提取并扩展密钥材料'),t('A KDF organizes entropy; it does not create entropy from an easy password.','KDF 整理熵，不会从易猜口令中创造熵。'),math('PRK = HKDF-Extract(salt, input_key_material)\nK_enc = HKDF-Expand(PRK, "protocol-v1/encryption", length)\nK_auth = HKDF-Expand(PRK, "protocol-v1/authentication", length)')+p(t('Salt and context/info have different roles. Salt need not be secret; info separates purposes and binds context. Use the protocol’s exact labels and sizes. Key establishment outputs should normally pass through the specified KDF before becoming AEAD keys.','Salt 与 context/info 的作用不同。Salt 不必保密；info 用于区分用途并绑定上下文。遵守协议规定的标签和长度。密钥建立输出通常应先经过指定 KDF，再用作 AEAD 密钥。')),['hkdf'])
        add('passwords',t('Password storage deliberately spends time and memory','口令存储有意消耗时间与内存'),t('A random salt prevents reusable cross-user precomputation, not single-user guessing.','随机 Salt 防止跨用户复用预计算，不防止针对单个用户猜测。'),p(t('Use a password-hashing design such as Argon2id with calibrated memory/time parameters and a unique salt. Store the algorithm version and parameters for future upgrades. Fast SHA-256, even with a salt, gives offline attackers a cheap guess loop. HKDF is not a password-hardening function. A pepper is an additional managed secret and introduces a separate recovery and rotation problem.','使用 Argon2id 等口令 Hash 方案，并校准内存 / 时间参数和唯一 Salt。保存算法版本及参数以便升级。快速 SHA-256 即使加 Salt，仍给离线攻击者提供便宜的猜测循环。HKDF 不是口令强化函数。Pepper 是额外托管秘密，会引入独立的恢复与轮换问题。')),['argon','hkdf'])
    elif page=='randomness':
        info=(t('Unpredictability starts<br><em>before the first key</em>','不可预测性<br><em>始于第一把密钥之前</em>'),t('Entropy sources, DRBGs, operating-system interfaces and the differences among keys, nonces and salts.','理解熵源、DRBG、操作系统接口，以及密钥、Nonce 和 Salt 的不同要求。'))
        add('pipeline',t('Entropy feeds deterministic expansion','熵支撑确定性扩展'),t('A DRBG can generate many bits without generating new physical entropy for every bit.','DRBG 可产生大量比特，而非每一位都产生新物理熵。'),p(t('A noise source plus conditioning and health tests supplies seed material. A cryptographic DRBG evolves state and produces pseudorandom output; its security depends on entropy, algorithm and state protection. SP 800-90B addresses entropy sources, 90A specifies DRBG mechanisms, and 90C combines them into RBG constructions. Statistical “random-looking” output alone does not establish unpredictability.','噪声源、调理及健康测试提供种子材料。密码 DRBG 演化状态并产生伪随机输出；安全依赖熵、算法和状态保护。SP 800-90B 讨论熵源，90A 定义 DRBG 机制，90C 把它们组合为 RBG 构造。统计上“像随机”本身不能证明不可预测。'))+math('H_min(X) = −log₂(max_x Pr[X=x])\nA 256-bit output does not imply a 256-bit unpredictable seed'),['90a','90b','90c'],'random-pipeline')
        add('roles',t('Random and unique are not synonyms','随机与唯一不是同义词'),t('The required property comes from the construction.','所需属性由构造决定。'),table([t('Value','数值'),t('Requirement','要求'),t('Common error','常见错误')],[
            (t('Secret key / token','秘密密钥 / Token'),t('Sufficient unpredictable entropy','足够的不可预测熵'),t('Timestamp seed, ordinary PRNG or leaked logs','时间戳种子、普通 PRNG 或日志泄漏')),
            ('GCM nonce',t('Unique per key; random allocation needs bounds','同一密钥下唯一；随机分配须控制上限'),t('Counter reset or cloned VM state','计数器复位或克隆 VM 状态')),
            (t('Authentication challenge','认证挑战'),t('Fresh, normally unpredictable and bound to request','新鲜、通常不可预测且绑定请求'),t('Accepting a caller’s nonce as the verifier challenge','把调用者提供的 Nonce 当成验证者挑战')),
            (t('Password salt','口令 Salt'),t('Unique/random across records; public','跨记录唯一 / 随机；公开'),t('Treating it as a secret or as password entropy','当作秘密或当作口令熵')),
            ('ECDSA scalar',t('Scheme-approved secure per-message generation','方案规定的安全逐消息生成'),t('Reused or biased values','复用或偏置值')),
        ]),['gcm','secrets','book'])
        add('api',t('Use the OS CSPRNG through a supported API','通过受支持接口使用 OS CSPRNG'),t('For Python, secrets is the intended interface for secret values.','Python 中 secrets 是面向秘密值的接口。'),code('import secrets\nkey = secrets.token_bytes(32)\ntoken = secrets.token_urlsafe(32)\nindex = secrets.randbelow(10)  # unbiased range sampling')+p(t('Do not seed a PRNG with time or use random / Math.random for keys. Avoid reducing a random byte modulo a range when it introduces bias. Embedded systems and early boot need an explicit entropy-ready design; forked processes, snapshots and restored generator state need implementation support. Hardware RNG instructions are inputs or interfaces to evaluate, not a universal proof of entropy.','不要用时间给 PRNG 播种，也不要用 random / Math.random 生成密钥。随机字节直接对范围取模可能引入偏置。嵌入式与早期启动需明确的熵就绪设计；进程 fork、快照和恢复生成器状态需要实现支持。硬件 RNG 指令是需要评估的输入或接口，并非通用熵证明。')),['secrets','90b','90c'])
    elif page=='theory':
        info=(t('Define the game<br><em>before claiming security</em>','声称安全前<br><em>先定义安全游戏</em>'),t('Probability, algebra, indistinguishability and reductions form the language of modern cryptography.','概率、代数、不可区分性与归约构成现代密码学的语言。'))
        add('math',t('The mathematics you actually need first','先补真正需要的数学'),t('Study each tool when an algorithm or proof gives it a job.','当算法或证明需要某个工具时再学习它。'),table([t('Tool','工具'),t('Use','用途'),t('First exercise','第一个练习')],[
            (t('Modular arithmetic','模算术'),t('RSA, DH, finite fields','RSA、DH、有限域'),t('Compute inverses with extended Euclid','用扩展 Euclid 求逆元')),
            (t('Groups / fields','群 / 域'),t('Discrete logs and elliptic-curve operations','离散对数与椭圆曲线运算'),t('Distinguish a field modulus from group order','区分域模数和群阶')),
            (t('Probability','概率'),t('Collision bounds, entropy, adversarial success','碰撞界、熵、攻击者成功率'),t('Derive the birthday approximation','推导生日碰撞近似')),
            (t('Complexity','复杂度'),t('Efficient adversaries and asymptotic security','高效攻击者与渐近安全'),t('Separate exponential growth from a concrete work budget','区分指数增长与实际工作预算')),
        ])+math('Pr[collision among q uniform n-bit values] ≈ 1 − exp(−q(q−1)/(2·2^n))\n# Approximation; uniform independent samples assumed'),['book','hac'])
        add('games',t('Security is a quantified attacker experiment','安全是量化的攻击者实验'),t('The oracle permissions matter as much as the algorithm name.','Oracle 权限与算法名称同样重要。'),table([t('Notion','安全概念'),t('Attacker capability','攻击者能力'),t('Winning condition','获胜条件')],[
            ('IND-CPA',t('Choose plaintexts; see encryption responses','选择明文；看到加密响应'),t('Distinguish which equal-length challenge message was encrypted','区分哪条等长挑战消息被加密')),
            ('IND-CCA',t('Also obtain permitted decryptions; not the challenge ciphertext','还能获得允许的解密；不能解密挑战密文'),t('Distinguish despite active ciphertext queries','在主动密文查询下仍能区分')),
            ('EUF-CMA',t('Obtain signatures on chosen messages','获得自选消息的签名'),t('Forge a valid signature on a new message','在新消息上伪造有效签名')),
            (t('Ciphertext integrity','密文完整性'),t('Observe authenticated encryptions','观察认证加密结果'),t('Create a fresh accepted ciphertext under the defined game','按游戏定义创造新且被接受的密文')),
        ]),['book'],'security-game')
        add('proofs',t('A reduction transfers a failure to an assumption','归约把失败转移到安全假设'),t('It is conditional reasoning, not an unconditional guarantee.','这是条件推理，不是无条件保证。'),p(t('A proof constructs an algorithm that uses a successful attacker to solve an assumed-hard problem or break a lower-level primitive. Inspect query limits, reduction loss, random-oracle or ideal-cipher assumptions and parameter sizes. RSA security is not simply a general equivalence to factoring; discrete-log, DH and lattice assumptions are distinct. IND-CPA alone does not imply integrity.','证明构造一个算法，利用成功的攻击者求解假定困难的问题，或破坏底层原语。应看查询上限、归约损失、随机 Oracle 或理想密码假设及参数大小。RSA 安全不能简单视为与因数分解的一般等价关系；离散对数、DH 与格假设也不同。IND-CPA 本身不意味着完整性。'))+note(t('Match the model to implementation','让模型对应实现'),t('An abstract proof may not model timing, faults, parsing, weak randomness, key compromise or rollback. State those assumptions and test the actual boundary.','抽象证明可能未建模时序、故障、解析、弱随机性、密钥泄漏或回滚。应明确这些假设，并检查实际边界。')),['book'])
        add('perfect',t('Perfect secrecy and computational secrecy','完美保密与计算保密'),t('A one-time pad buys a strong property with demanding key management.','一次一密用严格的密钥管理换取很强的性质。'),p(t('A uniform independent key at least as long as the message, used only once, gives one-time-pad perfect secrecy. It does not provide integrity. Stream ciphers replace the long pad with computational pseudorandomness from a short secret; the assumptions and key/nonce rules change. Neither construction should be deployed as a homemade replacement for an authenticated protocol.','至少与消息等长、均匀且独立并只用一次的密钥，给一次一密带来完美保密性；但不提供完整性。流密码用短秘密派生的计算伪随机性替代长密钥垫，安全假设及 key/nonce 规则随之改变。两者都不应被自制成认证协议的替代品。')),['video','book'])
    elif page=='history':
        info=(t('From secret alphabets<br><em>to public designs</em>','从秘密字母表<br><em>到公开设计</em>'),t('A selective history of ideas: what each generation changed, and which lessons still survive.','按思想变化选取历史节点：每一代改变了什么，哪些教训延续至今。'))
        events=[
            ('CLASSICAL',t('Substitution, transposition and frequency analysis','替换、置换与频率分析'),t('Language statistics can survive a transformation. Classical ciphers are useful exercises, not modern confidentiality tools.','语言统计规律可在变换后保留。古典密码适合练习，不是现代保密工具。')),
            ('19th C.',t('Kerckhoffs’s design principle','Kerckhoffs 的设计原则'),t('Security should not rely on keeping the algorithm secret. Secret keys and public scrutiny become separate responsibilities.','安全不应依赖算法保密。秘密密钥管理与公开审查成为不同职责。')),
            ('1910s–40s',t('One-time pads, machines and information theory','一次一密、机械密码与信息论'),t('Vernam-style XOR, rotor systems and Shannon’s 1949 secrecy analysis made key reuse, structure and formal secrecy central questions.','Vernam 式 XOR、转子系统和 Shannon 1949 年的保密分析，把密钥复用、结构及形式化保密带入核心问题。')),
            ('1976',t('Public-key agreement','公钥协商'),t('Diffie and Hellman separated secret establishment from delivery of a pre-shared secret; authentication remained essential.','Diffie 与 Hellman 把秘密建立与预共享秘密交付分开，认证仍然不可或缺。')),
            ('1977–78',t('DES and RSA','DES 与 RSA'),t('DES became a public standard in 1977. RSA appeared in 1977 and its journal paper in 1978. Finite key size and scheme encoding became practical concerns.','DES 在 1977 年成为公开标准。RSA 于 1977 年提出，期刊论文于 1978 年发表。有限密钥长度与方案编码成为实际问题。')),
            ('1980s–90s',t('Proofs, elliptic curves and deployed protocols','安全证明、椭圆曲线与协议部署'),t('Computational definitions, zero knowledge, ECC and network protocols expanded the goals beyond hiding messages.','计算安全定义、零知识、ECC 和网络协议，把目标扩展到隐藏消息之外。')),
            ('2001–18',t('AES, AEAD, SHA-3 and TLS 1.3','AES、AEAD、SHA-3 与 TLS 1.3'),t('AES was standardized in 2001; SHA-3 in 2015; TLS 1.3 in 2018. Authenticated composition and safer protocol structure increasingly became defaults.','AES 于 2001 年标准化，SHA-3 于 2015 年标准化，TLS 1.3 于 2018 年发布。认证组合与更安全的协议结构逐渐成为默认选择。')),
            ('2024–26',t('PQC standards and hybrid deployment','PQC 标准与混合部署'),t('FIPS 203/204/205 arrived in 2024; RFC 10024 hybrid TLS key agreement in 2026. Migration now includes inventories, formats and interoperability.','FIPS 203/204/205 于 2024 年发布；RFC 10024 混合 TLS 密钥协商于 2026 年发布。迁移涉及清单、格式和互操作。')),
        ]
        timeline='<div class="timeline">'+''.join(f'<article class="timeline-item"><time>{year}</time><div><h3>{title}</h3><p>{text}</p></div></article>' for year,title,text in events)+'</div>'
        add('timeline',t('Read history as a change in assumptions','把历史看作假设的变化'),t('This timeline selects ideas rather than claiming a complete chronology.','这条时间线选择重要思想，不追求完整编年。'),timeline,['hac','dh-paper','rsa-paper','aes','sha3','tls','hybrid'])
        add('lessons',t('The recurring failure patterns','反复出现的失败模式'),t('The algorithm can be strong while the surrounding system remains weak.','算法可以很强，周围系统仍可能很弱。'),bullets([t('Small key spaces become searchable as computation improves.','计算进步让小密钥空间变得可搜索。'),t('Repeated pads, IVs or signature scalars reveal structure or secrets.','重复密钥垫、IV 或签名标量会泄漏结构或秘密。'),t('New cryptanalysis changes confidence in assumptions and parameter choices.','新的密码分析改变对假设和参数选择的信心。'),t('Protocol oracles, parsing and identity mistakes can bypass mathematically sound primitives.','协议 Oracle、解析及身份错误可绕开数学上可靠的原语。')]),['video','book'])
        add('reading',t('Compare an original paper with its modern use','比较原始论文与现代用法'),t('Keep historical significance separate from deployment advice.','区分历史意义与部署建议。'),p(t('Read the 1976 Diffie–Hellman paper, then compare its agreement idea with authenticated TLS 1.3. Read the 1978 RSA paper, then study OAEP and PSS in PKCS #1. The gap illustrates why a mathematical operation is not yet a complete secure construction. The Handbook is valuable for mathematics and history, but its older algorithm guidance should not drive current deployment choices.','读 1976 年 Diffie–Hellman 论文，再把协商思想与经过认证的 TLS 1.3 比较。读 1978 年 RSA 论文，再看 PKCS #1 中的 OAEP 与 PSS。这种差距说明数学操作还不是完整的安全构造。Handbook 对数学和历史很有价值，但不应按其旧算法指导作现代部署决策。')),['dh-paper','rsa-paper','rsa','hac'])
    elif page=='tls':
        info=(t('TLS combines primitives<br><em>into a channel</em>','TLS 把原语组合成<br><em>安全通道</em>'),t('Trace a TLS 1.3 handshake through agreement, authentication, key derivation and record protection.','沿 TLS 1.3 握手追踪协商、认证、密钥派生与记录保护。'))
        add('handshake',t('A certificate-authenticated TLS 1.3 exchange','基于证书认证的 TLS 1.3 交换'),t('The diagram follows a common ephemeral-DH server-authenticated handshake.','图中是常见的临时 DH、服务端认证握手。'),p(t('ClientHello offers versions, groups, key shares and signature algorithms. ServerHello selects parameters and contributes a share. HKDF derives handshake keys; the server’s remaining flight is encrypted. CertificateVerify signs a role-specific transcript; Finished authenticates the transcript with a derived key. The client validates trust and service identity before relying on application data. Client certificates, PSK resumption and HelloRetryRequest use additional or different paths.','ClientHello 提供版本、群、密钥份额及签名算法；ServerHello 选择参数并贡献份额。HKDF 派生握手密钥，服务端后续报文经过加密。CertificateVerify 签署带角色上下文的转录；Finished 以派生密钥认证转录。客户端在依赖应用数据前验证信任和服务身份。客户端证书、PSK 恢复与 HelloRetryRequest 有额外或不同路径。')),['tls'],'tls-flow')
        add('schedule',t('Different secrets serve different stages and directions','不同秘密服务不同阶段和方向'),t('Do not reuse a single raw DH value as every traffic key.','不要把原始 DH 值复用于所有流量密钥。'),table([t('Component','组件'),t('Job','职责'),t('Distinction','区别')],[
            ('(EC)DHE / PQ-T group',t('Establish keying material','建立密钥材料'),t('Chosen separately from the cipher suite','与密码套件分别选择')),
            ('CertificateVerify',t('Authenticate the transcript under a signing key','用签名密钥认证转录'),t('Not RSA key transport or bulk encryption','不是 RSA 密钥传输或批量加密')),
            ('HKDF',t('Derive handshake/application/exporter secrets','派生握手 / 应用 / exporter 秘密'),t('Context and labels separate stages and roles','上下文及标签分离阶段与角色')),
            ('AEAD',t('Protect records using traffic keys and per-record nonces','使用流量密钥及逐记录 Nonce 保护记录'),t('TLS sequence state and usage bounds still matter','TLS 序号状态及使用上限仍重要')),
        ])+p(t('TLS_AES_128_GCM_SHA256 names the record AEAD and key-schedule hash. In TLS 1.3 it does not name the certificate’s signature scheme or the key-agreement group. Forward secrecy is a property of the actual handshake and key lifecycle; PSK-only resumption differs from PSK with ephemeral agreement.','TLS_AES_128_GCM_SHA256 指记录 AEAD 和密钥派生 Hash。在 TLS 1.3 中，它不指定证书签名方案或密钥协商群。前向安全取决于实际握手和密钥生命周期；仅 PSK 恢复与 PSK 加临时密钥协商不同。')),['tls','hkdf'])
        add('pitfalls',t('Encryption does not complete endpoint verification','加密没有完成端点验证'),t('Protocol settings and application semantics affect the result.','协议设置和应用语义会影响结果。'),bullets([t('Validate the chain and intended service name; do not disable certificate verification to fix connectivity.','验证证书链和预期服务名；不要以关闭证书验证修复连接。'),t('0-RTT early data can be replayed and lacks the same forward-secrecy properties as later application data. Limit it to explicitly safe operations with replay-aware design.','0-RTT 早期数据可被重放，且没有后续应用数据相同的前向安全属性；仅用于经过明确设计、能处理重放的安全操作。'),t('TLS ends at the configured endpoint. A reverse proxy termination is not automatic end-to-end application encryption.','TLS 终止于配置端点。反向代理终止不自动等于端到端应用加密。'),t('Treat session tickets and private keys as managed secrets. Audit negotiated parameters, not only offered configuration.','把会话票据与私钥作为托管秘密；检查协商结果，而非仅检查提供的配置。')]),['tls'])
        add('related',t('Other protocols reuse the vocabulary differently','其他协议以不同方式复用这些概念'),t('Read their trust and state models independently.','分别阅读各协议的信任与状态模型。'),table([t('Protocol / framework','协议 / 框架'),t('Purpose','用途'),t('Key question','关键问题')],[
            ('SSH',t('Remote-access transport and host authentication','远程访问传输及宿主认证'),t('How is the host key enrolled, checked and rotated? Old baseline cipher lists are historical.','宿主密钥如何登记、验证和轮换？旧基础规范的密码列表具有历史性。')),
            ('HPKE',t('KEM + KDF + AEAD for public-key encryption contexts','KEM + KDF + AEAD，建立公钥加密上下文'),t('Which mode authenticates the sender, and where is replay handling?','哪种模式认证发送者，重放处理在哪里？')),
            ('Noise',t('Handshake framework with selected key patterns','按密钥模式选择握手的框架'),t('Which static keys are pre-known and authenticated?','哪些静态密钥预先已知并经过认证？')),
            ('SPDM',t('Device authentication, measurement exchange and sessions','设备认证、度量交换与会话'),t('Who supplies device trust anchors and reference values?','谁提供设备信任锚和参考值？')),
        ]),['ssh','hpke','noise','spdm-hub'])
    elif page=='spdm':
        info=(t('SPDM authenticates devices<br><em>and exchanges measurements</em>','SPDM 认证设备<br><em>并交换度量</em>'),t('Security Protocol and Data Model: requester/responder roles, negotiated capabilities and deployment policy.','Security Protocol and Data Model：Requester / Responder、协商能力与部署策略。'))
        add('scope',t('A device-security protocol with explicit roles','具有明确角色的设备安全协议'),t('This chapter uses published DSP0274 1.4.1; deployed endpoints may support older subsets.','本章依据已发布 DSP0274 1.4.1；部署端点可能只支持较旧子集。'),p(t('A requester discovers and authenticates a responder, retrieves supported measurements and may establish a secure session. Certificate chains or provisioned raw public keys and PSK modes have different trust setups. SPDM negotiation describes version, algorithms and capabilities; it does not by itself decide whether a device or firmware version is acceptable.','Requester 发现并认证 Responder，获取受支持的度量，并可建立安全会话。证书链、预配置原始公钥和 PSK 模式具有不同信任配置。SPDM 协商版本、算法及能力，不自行决定设备或固件版本是否可接受。'))+note(t('SPDM is not a transport or PCIe traffic cipher','SPDM 不是传输层，也不是 PCIe 流量密码'),t('Bindings carry SPDM over a transport such as MCTP or PCIe DOE. Secured-message specifications protect supported session messages; other mechanisms such as PCIe IDE have separate data-path roles.','Binding 把 SPDM 放在 MCTP 或 PCIe DOE 等传输上。安全消息规范保护受支持的会话消息；PCIe IDE 等机制承担独立的数据路径职责。')),['spdm','spdm-pdf','spdm-hub'])
        add('flow',t('Trace negotiation, identity and measured state','追踪协商、身份和度量状态'),t('The diagram is one certificate-based path; capabilities select optional branches.','图中是一条证书模式路径；可选分支取决于能力。'),table([t('Message family','消息组'),t('Question','回答什么'),t('Policy still needed','仍需的策略')],[
            ('GET_VERSION / GET_CAPABILITIES / NEGOTIATE_ALGORITHMS',t('Which protocol and algorithms can both sides use?','双方能使用哪些协议及算法？'),t('Allowed versions and mandatory security capabilities','允许的版本和必需安全能力')),
            ('GET_DIGESTS / GET_CERTIFICATE / CHALLENGE',t('Which identity key is presented, and is it possessed?','提交哪个身份密钥，是否持有它？'),t('Enrollment, chain/key validation and challenge/transcript checking','登记、证书链 / 密钥验证及挑战 / 转录检查')),
            ('GET_MEASUREMENTS',t('What supported firmware/configuration measurements are reported?','报告哪些受支持的固件 / 配置度量？'),t('Signed or session-bound response, freshness and reference-value appraisal','签名或会话绑定响应、新鲜度及参考值评估')),
            ('KEY_EXCHANGE / FINISH',t('Can a negotiated secure session be established?','能否建立协商后的安全会话？'),t('Identity binding, key schedule and secured-message limits','身份绑定、密钥派生与安全消息上限')),
        ]),['spdm-pdf','libspdm'],'spdm-flow')
        add('trust',t('Authenticate a statement, then appraise its meaning','先认证声明，再评估其含义'),t('A valid response from a genuine device can report an unacceptable firmware state.','真实设备的有效响应也可能报告不可接受的固件状态。'),p(t('Check the trust anchor, certificate/raw-key model, expected requester/responder role, negotiated algorithms, response transcript and challenge. Then identify the measurement block type and collection boundary, and compare with approved references. Unknown data, missing mandatory blocks and stale or rollback-prone state need a defined failure policy. Authentication is not authorization to access DMA, keys or resources.','检查信任锚、证书 / 原始公钥模型、预期角色、协商算法、响应转录及挑战。然后识别度量块类型与收集边界，并比较批准的参考值。未知数据、缺失必需块、旧状态或可回滚状态都需要定义好的失败策略。认证不等于获准访问 DMA、密钥或资源。')),['spdm-pdf'])
        add('lab',t('Read libspdm at the message boundary','在消息边界阅读 libspdm'),t('A reproducible source exercise works without buying a device.','不购买设备也能做可复现的源码练习。'),bullets([t('Pin a libspdm revision and its supported specification versions. Map requester and responder handlers for one message family.','固定 libspdm 版本及所支持规范版本，定位一组消息的 Requester / Responder 处理函数。'),t('Follow transcript accumulation, signature verification and key derivation. Separate crypto adapters from transport and certificate provisioning.','追踪转录累积、验签和密钥派生；分开密码适配层、传输和证书配置。'),t('Use project tests or an appropriate emulator to record version/algorithm negotiation, then reject an altered signature or unapproved measurement in your appraisal layer.','用项目测试或适当模拟器记录版本 / 算法协商，再在评估层拒绝修改过的签名或未批准的度量。'),t('Document which security decision the reference implementation makes and which decision remains with your integrator policy.','记录参考实现作出了哪些安全决策，哪些留给集成者策略。')]),['libspdm','spdm-pdf'])
    elif page=='applied':
        info=(t('Make the key lifecycle<br><em>part of the design</em>','让密钥生命周期<br><em>成为设计的一部分</em>'),t('Storage, identity, transport and software delivery turn cryptographic assumptions into operational responsibilities.','存储、身份、传输及软件交付，把密码假设变成运维职责。'))
        add('envelope',t('Envelope encryption separates data and key control','信封加密分离数据与密钥控制'),t('A data-encryption key protects an object; a managed key protects that key.','数据加密密钥保护对象；托管密钥保护该密钥。'),p(t('Generate a DEK with a CSPRNG, encrypt the object with AEAD, and wrap/protect the DEK using a KMS/HSM-managed KEK or a defined recipient scheme. Store nonce, tag, algorithm/version, authenticated metadata and wrapped key together. KEK rotation can rewrap DEKs; a compromised DEK normally requires new data encryption. KMS authorization, tenant binding and audit are still essential.','用 CSPRNG 生成 DEK，以 AEAD 加密对象，再使用 KMS/HSM 托管 KEK 或规定的接收者方案保护 DEK。一起存储 Nonce、Tag、算法 / 版本、认证元数据及包裹密钥。KEK 轮换可重新包裹 DEK；DEK 泄漏通常需要重新加密数据。KMS 授权、租户绑定和审计仍然必需。')),['keymgmt','library'],'envelope')
        add('uses',t('Match the primitive to the workflow','让原语对应工作流程'),t('Several recurring applications need more than one building block.','多种常见应用需要不止一种积木。'),table([t('Application','应用'),t('Composition','组合'),t('Hidden engineering obligation','容易遗漏的工程职责')],[
            (t('Password database','口令数据库'),'Argon2id + salt',t('Parameter upgrades, rate limits and recovery design','参数升级、速率限制与恢复设计')),
            (t('API / login token','API / 登录 Token'),t('CSPRNG + protected storage / validation','CSPRNG + 受保护存储 / 验证'),t('Expiry, scope, revocation and no secret logging','有效期、范围、撤销及不记录秘密')),
            (t('Signed firmware / artifact','签名固件 / 制品'),t('Signature + trusted key + canonical manifest','签名 + 可信公钥 + 规范清单'),t('Version/rollback policy and key recovery','版本 / 防回滚策略与密钥恢复')),
            (t('Secure network channel','安全网络通道'),'TLS / defined AKE + AEAD',t('Endpoint identity, replay state and termination boundaries','端点身份、重放状态与终止边界')),
            (t('Device identity / measurement','设备身份 / 度量'),'SPDM + enrollment + appraisal',t('Reference-value ownership and device lifecycle','参考值归属及设备生命周期')),
        ]),['argon','tls','spdm-pdf','keymgmt'])
        add('implementation',t('Correct mathematics still needs a robust implementation','正确数学仍需可靠实现'),t('The platform can expose secrets through behavior.','平台行为可以暴露秘密。'),p(t('Use maintained high-level library APIs. Avoid data-dependent secret branches, variable-time comparisons, unsafe parsing and exposing decryption distinctions as an oracle. Constant-time source code needs compiler/platform validation; hardware acceleration is not an automatic absence of side channels. Fault handling, key erasure and crash recovery have their own assumptions.','使用维护中的高层库接口。避免依赖秘密的数据分支、变时比较、不安全解析，或把解密错误差异暴露为 Oracle。Constant-time 源码仍需编译器 / 平台验证；硬件加速不意味着没有侧信道。故障处理、密钥擦除和崩溃恢复也有自己的假设。'))+bullets([t('Review message formats, algorithms, nonce state and key ownership before reviewing API calls.','先审查消息格式、算法、Nonce 状态和密钥归属，再审查 API 调用。'),t('Test tampering, wrong key, wrong context, stale messages, malformed lengths and rollback behavior.','测试篡改、错误密钥、错误上下文、旧消息、畸形长度及回滚行为。'),t('Document library versions, supported profiles and interoperability vectors.','记录库版本、受支持 Profile 与互操作测试向量。')]),['library','book'])
        add('lifecycle',t('Generation is only the first key-management step','生成只是密钥管理的第一步'),t('Plan how trust changes over time.','规划信任如何随时间变化。'),p(t('Inventory keys by purpose, owner, algorithm, strength, storage location and cryptoperiod. Plan provisioning, backup/recovery, rotation, revocation, compromise response and destruction. An HSM can restrict key extraction but cannot fix an overly broad signing or decrypt authorization policy. Separate signing, wrapping, encryption and authentication keys.','按用途、所有者、算法、强度、存储位置及密码使用期盘点密钥。规划配置、备份 / 恢复、轮换、撤销、泄漏响应和销毁。HSM 可限制密钥导出，但不能修复过宽的签名或解密授权策略。应分离签名、包裹、加密和认证密钥。')),['keymgmt'])
    elif page=='future':
        info=(t('New assumptions,<br><em>new deployment questions</em>','新安全假设<br><em>带来新部署问题</em>'),t('PQC, zero knowledge, threshold computation and encrypted computation broaden what cryptography can do.','PQC、零知识、阈值计算与加密计算扩展密码学能力。'))
        add('pqc',t('Quantum threats change public-key assumptions','量子威胁改变公钥安全假设'),t('PQC runs on classical hardware; it is not quantum communication.','PQC 运行在经典硬件上，不是量子通信。'),p(t('A sufficiently capable fault-tolerant quantum computer running Shor’s algorithm threatens factoring and discrete-log systems, including RSA and common DH/ECC. Grover-style generic search changes symmetric-key and preimage work factors under an idealized model; practical costs and hash collision analysis differ. Do not apply one “halve every security bit” rule to every primitive.','具备足够能力的容错量子计算机运行 Shor 算法，会威胁因数分解与离散对数体系，包括 RSA 及常见 DH/ECC。Grover 式通用搜索在理想模型下改变对称密钥及原像工作量；实际成本与 Hash 碰撞分析不同。不能对所有原语套用“安全位数全部减半”。'))+table([t('Standard','标准'),t('Role','用途'),t('Family / status','类别 / 状态')],[
            ('FIPS 203 / ML-KEM',t('Key encapsulation','密钥封装'),t('Module-lattice; published 2024','Module-lattice；2024 年发布')),
            ('FIPS 204 / ML-DSA',t('Digital signatures','数字签名'),t('Module-lattice; published 2024','Module-lattice；2024 年发布')),
            ('FIPS 205 / SLH-DSA',t('Digital signatures','数字签名'),t('Stateless hash-based; published 2024','无状态 Hash 签名；2024 年发布')),
        ])+p(t('ML-KEM establishes a shared secret through encapsulation/decapsulation; it does not directly encrypt a file or authenticate a sender. Pair it with a defined KDF/AEAD protocol. Other selected or candidate schemes have separate standardization status; consult NIST rather than treating selection as publication.','ML-KEM 通过封装 / 解封装建立共享秘密，不直接加密文件，也不认证发送者。应结合定义好的 KDF / AEAD 协议。其他已选中或候选方案各有标准化状态；查询 NIST，不把选中等同于标准发布。')),['mlkem','mldsa','slhdsa','pqc'],'kem')
        add('migration',t('Migration starts with data lifetime and inventory','迁移从数据寿命与清单开始'),t('Harvest-now-decrypt-later matters before a cryptographically relevant quantum machine exists.','“现在收集、以后解密”在相关量子计算机出现之前就有意义。'),p(t('Classify long-lived confidentiality needs and signature-verification lifetimes. Inventory certificates, KEM/DH uses, HSM firmware, wire formats and update mechanisms. Measure larger keys/signatures/ciphertexts, latency, memory and failure handling. Hybrid agreement uses a defined combiner; informal concatenation or fallback can defeat the intended property. RFC 10024, published August 2026, specifies TLS 1.3 ECDHE–ML-KEM groups including X25519MLKEM768. That upgrade protects agreement; certificate signatures remain a separate migration track.','分类长期机密性需求及签名验证寿命。盘点证书、KEM/DH 用途、HSM 固件、消息格式和更新机制。评估更大的密钥 / 签名 / 密文、延迟、内存及失败处理。混合协商使用规定的组合方式，随意拼接或回退可破坏预期属性。2026 年 8 月发布的 RFC 10024 定义了包括 X25519MLKEM768 的 TLS 1.3 ECDHE–ML-KEM 群。它升级密钥协商；证书签名是独立迁移路线。')),['hybrid','pqc','keymgmt'])
        add('frontier',t('Other directions answer different questions','其他方向回答不同问题'),t('Understand the function and threat model before comparing maturity.','比较成熟度前，先理解功能与威胁模型。'),table([t('Direction','方向'),t('What it enables','能力'),t('First caveat','首先要问什么')],[
            (t('Zero-knowledge proofs','零知识证明'),t('Prove a statement without revealing its witness','不泄漏见证地证明声明'),t('What statement, setup and soundness assumptions are used?','声明、Setup 与可靠性假设是什么？')),
            (t('Threshold signatures / MPC','阈值签名 / MPC'),t('Split signing or jointly compute across parties','分散签名或多方联合计算'),t('What corruption threshold, availability and malicious-party model apply?','腐败阈值、可用性及恶意参与者模型是什么？')),
            (t('FHE','全同态加密'),t('Evaluate supported computations on encrypted data','在加密数据上计算受支持函数'),t('What performance, leakage and result-integrity guarantees hold?','性能、泄漏及结果完整性保证是什么？')),
            (t('Crypto agility','密码敏捷性'),t('Change algorithms and parameters under controlled policy','在受控策略下更换算法与参数'),t('Can migration avoid downgrade, state reuse and ambiguous formats?','迁移能否避免降级、状态复用和格式歧义？')),
        ]),['book','pqc'])
        add('next',t('Choose one direction for deeper study','选择一个方向深入学习'),t('The foundations here stand on their own; specialist sites are optional next steps.','本站基础自成体系；专项网站只是可选的下一步。'),p(t('For PQC mechanisms and migration, continue with the Quantum & PQC Atlas. For LWE, lattices and lattice constructions, use the Lattice Cryptography Atlas. For ZK/MPC, begin with the protocol chapters of Boneh–Shoup and implement only a toy exercise before studying a maintained system.','PQC 机制与迁移可继续阅读量子与 PQC 专题。LWE、格及格构造可阅读格密码专题。ZK/MPC 可从 Boneh–Shoup 协议章节入手，先做小型教学练习，再研究维护中的系统。'))+f'<p><a href="https://shundazhang.github.io/quantum-pqc-atlas/">Quantum &amp; PQC Atlas ↗</a> · <a href="https://shundazhang.github.io/lattice-crypto-atlas/">Lattice Cryptography Atlas ↗</a></p>', ['book'])
    else:raise ValueError(page)
    return info,parts
